// Shown when the form answers can't be used (missing fields, bad email, daily limit)
const p = $json.problem;
if (p === 'spam') return [{ json: { html: page('Thanks', '<div class="card"><h1>Thanks!</h1><p class="muted">We got your message.</p></div>') } }];
