.kpi{background:#fff;border:1px solid #e3e8ef;border-radius:12px;padding:14px}.kpi b{display:block;font-size:26px;color:#0f2a4a}
a{color:#1d4ed8}footer{font-size:13px;color:#6b7485;text-align:center;margin-top:24px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · bookings go to a demo calendar and no real call takes place.</footer></main></body></html>`;
const notFoundPage = () => page('Link not found', `<div class="card"><h1>We couldn't find that booking link</h1><p class="muted">It may be old or mistyped. Fill in the short form again and you'll get a fresh link.</p><a class="btn" href="${FORM_URL}">Open the form</a></div>`);

// email helpers (Gmail API needs the whole message as base64url)
const b64 = (s) => (typeof Buffer !== 'undefined' ? Buffer.from(String(s), 'utf8').toString('base64') : btoa(unescape(encodeURIComponent(String(s)))));
const wrap76 = (s) => s.replace(/.{1,76}/g, (m) => m + '\r\n');
const mime = ({ to, subject, text, html, ics, id }) => {
  const mix = 'mix_' + id, alt = 'alt_' + id;
  const m = ['From: "Harborline Software (demo)" <you@yourdomain.com>', 'To: ' + to, 'Subject: =?UTF-8?B?' + b64(subject) + '?=', 'MIME-Version: 1.0', `Content-Type: multipart/mixed; boundary="${mix}"`, '', '--' + mix, `Content-Type: multipart/alternative; boundary="${alt}"`, '', '--' + alt, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(text)), '--' + alt, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(html)), '--' + alt + '--', ''];
  if (ics) m.push('--' + mix, 'Content-Type: application/ics; name="invite.ics"', 'Content-Disposition: attachment; filename="invite.ics"', 'Content-Transfer-Encoding: base64', '', wrap76(b64(ics)));
  m.push('--' + mix + '--', '');
  return b64(m.join('\r\n')).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};
const emailShell = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1d2433;font-size:15px;line-height:1.55"><p style="font-weight:700;color:#0f2a4a;font-size:18px;margin:0 0 16px">Harborline Software</p>${inner}<hr style="border:0;border-top:1px solid #e3e8ef;margin:24px 0 12px"><p style="font-size:12px;color:#6b7485">Sent by a live n8n demo built by Aqib ur Rehman. Harborline Software is a fictional company and no real call will take place.</p></div>`;
// ---- end shared helpers ----

// Decide: is the time still free? If yes, reserve it and prepare the calendar event, HubSpot deal and email
const req = $('Check booking request').first().json;
const store = $getWorkflowStaticData('global');
const lead = (store.leads || []).find((l) => l.token === req.token) || null;
const cal = $json.calendars && $json.calendars[CAL_ID];
let problem = req.problem;
if (!problem && (!cal || cal.errors || !Array.isArray(cal.busy))) problem = 'calendar';
if (!problem && cal.busy.length) problem = 'taken';
if (!problem && (store.leads || []).some((l) => l.booking && l.booking.start === req.startIso)) problem = 'taken';
if (problem) return [{ json: { proceed: false, problem, token: req.token } }];

const start = uk(req.startIso), end = uk(req.endIso);
const when = `${start.toFormat('cccc d LLLL')}, ${start.toFormat('HH:mm')}–${end.toFormat('HH:mm')} UK time`;
lead.booking = { start: req.startIso, end: req.endIso, when, status: 'Reserving' };
store.bookDay.count += 1;

const agendaTxt = lead.agenda.map((a, i) => `${i + 1}. ${a}`).join('\n');
const eventBody = {
  summary: `Discovery call: ${lead.name}${lead.company ? ' (' + lead.company + ')' : ''}`,
  description: `Booked through the Harborline lead-qualification demo (n8n).\n\nLead score: ${lead.score}/100 (${lead.tier})\nEmail: ${lead.email}\nCompany size: ${lead.size}\nBudget: ${lead.budget}\nTimeline: ${lead.timeline}\n\nWhat they want automated:\n${lead.need}\n\nAI summary: ${lead.summary}\n\nAgenda:\n${agendaTxt}`,
  start: { dateTime: req.startIso, timeZone: 'Europe/London' },
  end: { dateTime: req.endIso, timeZone: 'Europe/London' },
  colorId: lead.tier === 'hot' ? '11' : '5',
};
const amount = { 'Under $500': 400, '$500 – $2,000': 1500, '$2,000 – $5,000': 3500, '$5,000 or more': 6000 }[lead.budget] ?? 1000;
const dealBody = {
  properties: {
    dealname: `${lead.company || lead.name} – automation project`,
    pipeline: 'default',
    dealstage: 'appointmentscheduled',
    amount: String(amount),
    closedate: start.plus({ days: 30 }).toUTC().toISO(),
    description: `Discovery call ${when}. AI lead score ${lead.score}/100 (${lead.tier}). ${lead.summary}`,
  },
  associations: lead.hubspotContactId ? [{ to: { id: String(lead.hubspotContactId) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 3 }] }] : [],
};

const icsEsc = (s) => String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const fold = (line) => line.match(/.{1,73}/g).join('\r\n ');
const dt = (x) => x.toUTC().toFormat("yyyyLLdd'T'HHmmss'Z'");
const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Harborline demo//n8n//EN', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'BEGIN:VEVENT',
  `UID:${lead.token}@harborline-demo`, `DTSTAMP:${dt(DateTime.now())}`, `DTSTART:${dt(start)}`, `DTEND:${dt(end)}`,
  'SUMMARY:Discovery call with Harborline Software (demo)',
  fold('DESCRIPTION:' + icsEsc('Agenda:\n' + agendaTxt + '\n\nThis is a demo booking. Harborline Software is fictional.')),
  'LOCATION:Online (demo)', 'END:VEVENT', 'END:VCALENDAR', ''].join('\r\n');

const html = emailShell(`<p>Hi ${esc(lead.first)},</p><p>Your free 30-minute discovery call is booked for <b>${esc(when)}</b>. The calendar invite is attached (invite.ics), so you can add it to your calendar in one click.</p><p style="margin-bottom:4px"><b>What we'll cover</b></p><ol style="margin-top:4px">${lead.agenda.map((a) => `<li>${esc(a)}</li>`).join('')}</ol><p>Need another time? Just reply to this email.</p><p>Talk soon,<br>The Harborline team</p>`);
const text = `Hi ${lead.first},\n\nYour free 30-minute discovery call is booked for ${when}. The calendar invite is attached (invite.ics).\n\nWhat we'll cover:\n${agendaTxt}\n\nNeed another time? Just reply to this email.\n\nThe Harborline team\n\n(Sent by a live n8n demo built by Aqib ur Rehman. Harborline Software is fictional and no real call will take place.)`;
const raw = mime({ to: lead.email, subject: `Booked: your Harborline call on ${start.toFormat('ccc d LLL')} at ${start.toFormat('HH:mm')} (UK)`, text, html, ics, id: lead.token });

return [{ json: { proceed: true, token: lead.token, startIso: req.startIso, endIso: req.endIso, when, eventUrl: 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(CAL_ID) + '/events', eventBody, dealBody, raw } }];

// Save the booking on the lead and prepare the Google Sheets log row
const d = $('Decide booking').first().json;
const ev = $('Calendar – create event').first().json;
const deal = $('HubSpot – create deal').first().json;
const mail = $('Gmail – send confirmation').first().json;
const store = $getWorkflowStaticData('global');
const lead = (store.leads || []).find((l) => l.token === d.token);
const eventOk = !!ev.id, dealOk = !!deal.id, mailOk = !!mail.id;
lead.booking = { start: d.startIso, end: d.endIso, when: d.when, eventId: ev.id || null, status: eventOk ? 'Booked' : 'Calendar error' };
lead.hubspotDealId = deal.id || null;
lead.status = 'Call booked';
lead.emailSent = mailOk;
const time = DateTime.now().setZone('Europe/London').toFormat('yyyy-LL-dd HH:mm');
return [{ json: { ...d, raw: undefined, eventOk, dealOk, mailOk, dealId: deal.id || null, lead, row: [time, 'Call booked', lead.name, lead.company, lead.email, lead.score, lead.tier, `${d.when} · HubSpot deal ${deal.id || 'not created'}`] } }];

